 db.leadStatuses??={};db.branchRules??={a:[{code:'NTH',label:'North branch',match:'NTH',level:'campaign',type:'prefix',aliases:'north'},{code:'STH',label:'South branch',match:'STH',level:'campaign',type:'prefix',aliases:'south'}]};
