const shiftIso=(iso,n)=>{const d=new Date(iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
// live: feedback may cover the past year up to today; demo data: 1-24 Oct 2026
const feedbackMin=()=>window.__LIVE?shiftIso(todayIST(),-365):'2026-10-01';
const feedbackMax=()=>window.__LIVE?todayIST():'2026-10-24';
const validFeedbackDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(String(d))&&!isNaN(Date.parse(d))&&d>=feedbackMin()&&d<=feedbackMax();
const MONTHS={jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};
// '22 Oct', 'Oct 22', '22 October 2026', '2026-10-22', '22/10/2026' (day first) -> ISO date, or null
function feedbackDate(line){
  const iso=line.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);if(iso)return `${iso[1]}-${iso[2]}-${iso[3]}`;
  let d,m,y;
  const a=line.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s*(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?(?:,?\s+(\d{4}))?/i);
  const b=line.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s+(\d{4}))?/i);
  const c=line.match(/\b(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4})\b/);
  if(a){d=+a[1];m=MONTHS[a[2].toLowerCase()];y=a[3]&&+a[3]}else if(b){d=+b[2];m=MONTHS[b[1].toLowerCase()];y=b[3]&&+b[3]}else if(c){d=+c[1];m=+c[2];y=+c[3]<100?2000+ +c[3]:+c[3]}else return null;
  if(!m||d<1||d>31)return null;
  const today=window.__LIVE?todayIST():'2026-10-24';y=y||+today.slice(0,4);
  let out=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
  if(out>today&&!(a&&a[3])&&!(b&&b[3])&&!c)out=`${y-1}${out.slice(4)}`; // '28 Dec' typed in January means last year
  return out;
}
