   const buckets={qualified:0,booked:0,won:0,junk:0,none:0};for(const r of records){const st=statuses(id).find(s=>s.id===r.status);if(st)buckets[st.bucket]+=Number(r.count)||0;}
   const covered=[...new Set(records.map(r=>window.__LIVE?r.date:Number(r.date.slice(-2))))];let metrics;
   if(scope.adset)metrics=adset(id,scope.adset,covered)||complete({spend:0,leads:0,clicks:0,impressions:0});else if(scope.campaign)metrics=campaign(id,scope.campaign,covered)||complete({spend:0,leads:0,clicks:0,impressions:0});else if(Object.hasOwn(scope,'branch'))metrics=sumMetrics(campaigns(id,covered,'all').filter(c=>c.branch===scope.branch));else metrics=aggregate(clientAccounts(id),covered);
