 function fullReport(c,page='creatives'){if(!window.__LIVE)return`<div class="empty-state"><h2>The full report needs live Meta data.</h2></div>`;const ds=days(),acc=clientAccounts(c.id).find(a=>a.platform==='meta'&&a.ads?.length);if(!acc)return`<div class="empty-state"><h2>Ad-level data for this client is still syncing.</h2><p>Try again in a minute.</p></div>`;const src=`/${page}?embed=1&from=${ds[0]}&to=${ds.at(-1)}&account=${encodeURIComponent(acc.name||c.name)}`;return filters(false)+`<iframe class="report-frame" title="Full report for ${esc(c.name)}" src="${src}" style="width:100%;border:0;min-height:600px;display:block" onload="(f=>{try{const d=f.contentDocument;const fit=()=>{f.style.height=d.documentElement.scrollHeight+'px'};new ResizeObserver(fit).observe(d.body);fit()}catch{}})(this)"></iframe>`}
function tabs(c){return`<div class="tabs">${[['overview','Overview'],['insights','Insights'],['report','Full report'],['campaigns','Campaigns'],['quality','Lead quality'],['review','AI review'],['accounts','Accounts'],['flags','Flags'],['configuration','Configuration']].map(([t,l])=>`<a href="#/clients/${c.id}/${t}" class="${state.tab===t?'active':''}">${l}${t==='quality'?'<span class="badge neutral">NEW</span>':''}</a>`).join('')}</div>`}
 function breadcrumbs(c,cp=null,as=null,ad=null){return`<div class="drill-breadcrumbs"><a href="#/portfolio">Portfolio</a>${icon('chevron',10)}<a href="#/clients/${c.id}">${esc(c.name)}</a>${cp?`${icon('chevron',10)}<a href="#/clients/${c.id}/campaigns/${cp.id}">${esc(cp.name)}</a>`:''}${as?`${icon('chevron',10)}<a href="#/clients/${c.id}/adsets/${as.id}">${esc(as.name)}</a>`:''}${ad?`${icon('chevron',10)}<span>${esc(ad.name)}</span>`:''}</div>`}
 function campaignTable(c,ds=days()){let list=campaigns(c.id,ds);list.sort((a,b)=>(quality(c.id,ds,{campaign:b.id}).bookings-quality(c.id,ds,{campaign:a.id}).bookings)||b.spend-a.spend);return`<section class="card table-card"><div class="card-header"><div><h2>Campaign performance</h2><p>Ranked by confirmed bookings, then spend</p></div><span class="badge neutral">${list.length} campaigns</span></div><div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Branch</th><th>Spend</th><th>Leads</th><th>Bookings</th><th>Cost / booking</th><th></th></tr></thead><tbody>${list.map(cp=>{const q=quality(c.id,ds,{campaign:cp.id});return`<tr class="clickable" data-action="go" data-value="clients/${c.id}/campaigns/${cp.id}" tabindex="0" aria-label="Open campaign ${esc(cp.name)}"><td><div class="client-name-cell">${platformIcon(cp.platform)}<div><strong>${esc(cp.name)}</strong><small>${adsets(c.id,cp.id,ds).length} ad ${cp.platform==='google'?'groups':'sets'}</small></div></div></td><td><span class="badge neutral">${cp.branch||'All'}</span></td><td>${money(cp.spend,c.currency)}</td><td>${num(cp.leads)}</td><td>${q.records.length?num(q.bookings):'—'}</td><td>${money(q.cpb,c.currency)}</td><td>${icon('chevron',13)}</td></tr>`}).join('')||'<tr><td colspan="7"><div class="empty-state">No campaigns for this platform.</div></td></tr>'}</tbody></table></div></section>`}
 function qualityMini(c){const q=quality(c.id);return`<section class="card section-pad"><div class="section-head"><h2>From leads to outcomes</h2><span class="badge neutral">7 days</span></div><div class="outcome-mini"><div><strong>${q.records.length?q.bookings:'—'}</strong><span>Bookings</span></div><div><strong>${q.records.length?q.wins:'—'}</strong><span>Won</span></div><div><strong>${money(q.cpb,c.currency)}</strong><span>Cost / booking</span></div></div><p class="subtext" style="line-height:1.7;margin:15px 0">${q.records.length?`${Math.round(q.coverage||0)}% feedback coverage · ${q.days} of 7 days reported`:'Add client feedback to understand the quality behind the lead count.'}</p><a class="text-link" href="#/clients/${c.id}/quality">Explore lead quality ${icon('arrow',12)}</a></section>`}
 function reportCard(c){const s=sent(c.id,'daily',sampleDate);return`<section class="card section-pad"><div class="section-head"><h2>Client report</h2><span class="badge ${s?'success':'warning'}">${s?'Marked sent':'Ready for handoff'}</span></div><p class="subtext" style="line-height:1.8;margin-bottom:15px">${esc(c.whatsappGroup||c.name+' · Updates')}<br>Internal delivery to Performance | CH</p><div class="report-card-actions"><button class="btn primary" data-action="v3-copy" data-id="${c.id}" data-kind="daily" data-date="${sampleDate}">${icon('copy',13)}Copy for WhatsApp</button><button class="btn" data-action="v3-download" data-id="${c.id}" data-kind="weekly">${icon('download',13)}Download PDF</button><button class="btn" data-action="v3-sent" data-id="${c.id}" data-kind="daily" data-date="${sampleDate}" ${!canEdit()||!c.reportEnabled?'disabled':''}>${icon(s?'checkCircle':'check',13)}${s?'Unmark as sent':'Mark as sent'}</button><button class="btn ghost" data-action="v3-generate" data-id="${c.id}" ${!canEdit()?'disabled':''}>${icon('file',13)}Generate PDF</button></div>${s?`<p class="cell-sub" style="margin-top:12px">Marked by ${esc(s.by)} · ${timeLabel(s.at)}</p>`:''}</section>`}
 function creativePreview(ad){return ad.thumbnail?`<img src="${esc(ad.thumbnail)}" alt="${esc(ad.name)} · supplied creative still" loading="lazy"/>`:ad.platform==='google'?`<div class="search-creative"><small>Sponsored · Search ad</small><strong>${esc(ad.name)}</strong><p>Explore services and request more information.</p><small>Sample text creative</small></div>`:`<span>${icon('file',27)}<small>Creative not supplied</small></span>`;}
 function levelQuality(c,m){const q=quality(c.id,days(),{adset:m.id});return `<section class="card section-pad level-quality"><div class="section-head"><div><h2>Ad-set lead quality</h2><p class="subtext">${q.days?'Confirmed outcomes tagged to this ad set':'No feedback has been tagged to this ad set yet'}</p></div><button class="btn small" data-action="v3-feedback-adset" data-id="${c.id}" data-value="${m.id}">Add outcomes</button></div>${q.days?`<div class="quality-metrics">${[['Qualified',q.qualified],['Bookings',q.bookings],['Cost / booking',money(q.cpb,c.currency)],['Junk',q.buckets.junk]].map(([l,v])=>`<div><strong>${v}</strong><small class="cell-sub">${l}</small></div>`).join('')}</div><p class="subtext">${q.days}/${days().length} days reported · ${Math.round(q.coverage||0)}% feedback coverage. Costs use only days with feedback.</p>`:'<p class="subtext">Campaign-level feedback stays at campaign level. Tag confirmed outcomes to this ad set to see its booking cost and quality.</p>'}</section>`;}
 function adCard(c,ad){return`<article class="ad-card"><a href="#/clients/${c.id}/ads/${ad.id}" class="ad-thumbnail" aria-label="Open ad ${esc(ad.name)}">${creativePreview(ad)}<i>${esc(ad.type)}</i></a><div class="ad-content"><a href="#/clients/${c.id}/ads/${ad.id}"><h3>${esc(ad.name)}</h3></a><p>${esc(ad.campaignName)}<br>${esc(ad.adsetName)}</p><div class="ad-metrics"><div><strong>${money(ad.spend,c.currency)}</strong><span>Spend</span></div><div><strong>${num(ad.leads)}</strong><span>Leads</span></div><div><strong>${pct(ad.ctr)}</strong><span>CTR</span></div></div><div class="ad-foot"><span>${num(ad.impressions)} impressions</span><span>${num(ad.clicks)} clicks</span></div><div class="ad-foot"><span>${money(ad.cpr,c.currency)} / result</span><span>${ad.platform==='meta'?num(ad.messages)+' conversations':'Search ad'}</span></div></div></article>`}
 function topAds(c){const list=allAds(c.id).filter(a=>state.platform==='all'||a.platform===state.platform).sort((a,b)=>b.spend-a.spend).slice(0,3);return`<section class="card section-pad"><div class="section-head"><div><h2>Top ads by spend</h2><p class="subtext">Drill into an ad for its full context.</p></div></div><div class="ad-grid compact">${list.map(a=>adCard(c,a)).join('')}</div></section>`}
 function clientPage(){const c=clientById(state.clientId);if(state.campaignId||state.adsetId||state.adId)return drillPage(c);const h=breadcrumbs(c)+`<div class="page-heading"><div class="client-hero">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${esc(c.sector)} · ${clientAccounts(c.id).length} ad accounts · ${c.currency}</p></div></div><div class="heading-actions"><button class="btn" data-action="v3-feedback-client" data-id="${c.id}">${icon('message',13)}Add feedback</button><button class="btn primary" data-action="v3-open-report" data-id="${c.id}">${icon('send',13)}Client report</button></div></div>`;let body='';switch(state.tab){case'review':body=`<div class="content-two"><div>${reviewPanel(c)}</div><div class="stack">${qualityMini(c)}${budgetCard(c)}${reportCard(c)}</div></div>`;break;case'quality':body=qualityPage(c);break;case'report':body=fullReport(c);break;case'insights':body=fullReport(c,'insights');break;case'campaigns':body=filters(false)+campaignTable(c)+`<div style="margin-top:20px">${topAds(c)}</div>`;break;case'accounts':body=filters(false)+accountTable(clientAccounts(c.id).filter(a=>state.platform==='all'||a.platform===state.platform));break;case'flags':body=flagList(ctx.flags().filter(f=>f.client===c.id));break;case'configuration':body=clientConfig(c);break;default:body=filters(false)+metricCards(c.id)+`<div class="content-two"><div class="stack">${campaignTable(c)}${chart(c.id)}${topAds(c)}${platformSplit(c)}</div><div class="stack">${qualityMini(c)}${reportCard(c)}${budgetCard(c)}</div></div>`;}return h+tabs(c)+body+bottomNote()}
 function levelTiles(c,m){return`<div class="metrics level-metrics">${[['Ad spend',money(m.spend,c.currency),'wallet',`${money(m.cpr,c.currency)} per result`],[m.conv!=null?'Results · conv. + leads':'Results · leads',num(m.results),'target',m.conv!=null?`${num(m.conv)} conversations · ${num(m.leads)} leads`:`${money(m.cpa,c.currency)} per lead`],['Impressions',num(m.impressions),'eye',`${num(m.clicks)} link clicks`],['Click-through rate',pct(m.ctr),'click',`${num(m.clicks)} clicks of ${num(m.impressions)}`]].map(([l,v,i,sub])=>`<section class="metric"><div class="metric-top">${l}${icon(i,14)}</div><div class="metric-value">${v}</div><div class="metric-comparison">${sub}</div></section>`).join('')}</div>`}
 function levelSummary(c,m,level){if(!c.aiLevelSummaries)return'';const summary=`${m.conv!=null?`${money(m.spend,c.currency)} spent for ${num(m.conv)} WhatsApp conversations (${money(m.conv?m.spend/m.conv:null,c.currency)} each) and ${num(m.leads)} leads, from ${num(m.clicks)} link clicks at ${pct(m.ctr)} CTR.`:`${num(m.leads)} leads from ${money(m.spend,c.currency)} in spend, at ${money(m.cpa,c.currency)} per lead.`} Compare confirmed bookings before reallocating budget; lead volume alone does not indicate quality.`;return`<div class="level-summary"><div class="workflow-icon">${icon('spark',17)}</div><div><strong>Performance perspective <span class="badge neutral">${window.__LIVE?(window.__LIVE.accounts.some(x=>x.ads?.length)?'Live Meta data · staff only':'Account total · staff only'):'Sample · staff only'}</span></strong><p>${esc(summary)}</p><small>${db.levelSummaries[m.id]?'Refreshed locally':window.__LIVE?'Rules-based, from live numbers':'Cached sample'} · ${level} · ≤ 40 words</small></div><button class="btn small" data-action="v3-refresh-summary" data-id="${m.id}" ${!canEdit()?'disabled':''}>${icon('refresh',12)}Refresh</button></div>`}
 function drillPage(c){let cp,as,ad,m,title,label;if(state.adId){ad=allAds(c.id).find(a=>a.id===state.adId);if(ad){as=adset(c.id,ad.adset);cp=campaign(c.id,ad.campaign);m=ad;title=ad.name;label='AD'}}else if(state.adsetId){as=adset(c.id,state.adsetId);if(as){cp=campaign(c.id,as.campaign);m=as;title=as.name;label=as.platform==='google'?'AD GROUP':'AD SET'}}else{cp=campaign(c.id,state.campaignId);if(cp){m=cp;title=cp.name;label='CAMPAIGN'}}if(!m)return`<div class="empty-state"><h2>This item is no longer mapped to this client.</h2><a href="#/clients/${c.id}" class="btn" style="margin-top:20px">Back to client</a></div>`;let body='';if(ad){body=levelSummary(c,ad,'Ad')+`<div class="content-two"><section class="card section-pad"><div class="ad-thumbnail large">${creativePreview(ad)}</div><p class="subtext" style="margin-top:16px">${ad.creativeSource|| (ad.platform==='google'?'Search ads use a text preview.':'No image was supplied for this ad.')} ${ad.type==='Video'?'Video preview is a still image.':''}</p></section><section class="card section-pad"><div class="section-head"><h2>Ad details</h2><span class="badge neutral">${esc(ad.type)}</span></div><div class="definition-list"><div><span>Campaign</span><strong>${esc(cp.name)}</strong></div><div><span>Ad ${ad.platform==='google'?'group':'set'}</span><strong>${esc(as.name)}</strong></div><div><span>Branch</span><strong>${ad.branch||'All'}</strong></div><div><span>Clicks</span><strong>${num(ad.clicks)}</strong></div><div><span>Cost per result</span><strong>${money(ad.cpr,c.currency)}</strong></div><div><span>Conversations</span><strong>${ad.platform==='meta'?num(ad.messages):'—'}</strong></div></div></section></div>`}else if(as){const list=ads(c.id,as.id).sort((a,b)=>b.spend-a.spend);body=levelSummary(c,as,'Ad set')+levelQuality(c,as)+`<div class="section-head"><h2>Ads in this ${as.platform==='google'?'ad group':'ad set'}</h2><span class="badge neutral">${list.length} ads · by spend</span></div><div class="ad-grid">${list.map(a=>adCard(c,a)).join('')}</div>`}else{const list=adsets(c.id,cp.id),prev=days().map(d=>typeof d==='string'?shiftDay(d,-days().length):d-days().length);body=levelSummary(c,cp,'Campaign')+`<section class="card table-card"><div class="card-header"><div><h2>Every ad ${cp.platform==='google'?'group':'set'}, in context</h2><p>Totals reconcile with the campaign above.</p></div><span class="badge neutral">${list.length} ad sets</span></div><div class="table-scroll"><table><thead><tr><th>Ad set / group</th><th>Spend</th><th>Impressions</th><th>Clicks</th><th>CTR</th><th>Results</th><th>Conversations</th><th>Cost / result</th><th>Spend Δ</th><th>Qualified</th><th>Bookings</th><th>Cost / booking</th><th>Junk</th><th></th></tr></thead><tbody>${list.map(s=>{const p=adset(c.id,s.id,prev)||{spend:0},q=quality(c.id,days(),{adset:s.id});return`<tr class="clickable" data-action="go" data-value="clients/${c.id}/adsets/${s.id}" tabindex="0" aria-label="Open ad set ${esc(s.name)}"><td><div style="display:flex;align-items:center;gap:10px;min-width:180px">${(()=>{const top=ads(c.id,s.id).filter(x=>x.thumbnail).sort((x,y)=>y.spend-x.spend)[0];return top?`<img src="${esc(top.thumbnail)}" alt="" referrerpolicy="no-referrer" loading="lazy" style="width:44px;height:44px;border-radius:8px;object-fit:cover;flex:none;background:#ebeef2">`:`<span style="width:44px;height:44px;border-radius:8px;flex:none;background:#ebeef2"></span>`})()}<div><strong>${esc(s.name)}</strong><small class="cell-sub">${s.branch||'All'} · ${ads(c.id,s.id).length} ads</small></div></div></td><td>${money(s.spend,c.currency)}</td><td>${num(s.impressions)}</td><td>${num(s.clicks)}</td><td>${pct(s.ctr)}</td><td>${num(s.results)}${s.conv!=null?'':' leads'}</td><td>${cp.platform==='meta'?num(s.messages):'—'}</td><td>${money(s.cpr,c.currency)}</td><td>${delta(calcDelta(s.spend,p.spend))}</td><td>${q.days?num(q.qualified):'No feedback'}</td><td>${q.days?num(q.bookings):'No feedback'}</td><td>${q.cpb!=null?money(q.cpb,c.currency):q.days?'No bookings':'No feedback'}</td><td>${q.days?num(q.buckets.junk):'No feedback'}</td><td>${icon('chevron',12)}</td></tr>`}).join('')}</tbody></table></div><div class="table-footer">Lead quality is shown only when feedback is tagged to this ad set. Campaign-level feedback is not copied into each row.</div></section>`}return breadcrumbs(c,cp,as,ad)+heading(esc(title),`${c.name} · ${m.platform==='meta'?'Meta Ads':'Google Ads'} · ${m.branch||'All branches'}`,`<button class="btn" data-action="v3-generate" data-id="${c.id}">${icon('file',13)}Generate client PDF</button>`,label)+filters(false,false)+levelTiles(c,m)+body+bottomNote()}

// Additional workflow views and handlers follow below.
 function qualityPage(c){const q=quality(c.id),ds=[16,17,18,19,20,21,22],byCampaign=campaigns(c.id,ds,'all').map(cp=>({cp,q:quality(c.id,ds,{campaign:cp.id})})).sort((a,b)=>b.q.bookings-a.q.bookings),history=db.leadHistory.filter(h=>h.client===c.id).slice().reverse();return`<div class="section-head"><div><h2>Lead quality</h2><p class="subtext">16–22 October · confirmed client outcomes</p></div><button class="btn primary" data-action="v3-feedback-client" data-id="${c.id}" ${!canEdit()?'disabled':''}>${icon('plus',13)}Add client feedback</button></div><div class="quality-metrics">${[['Qualified',q.qualified,money(q.cpq,c.currency)+' / qualified'],['Bookings',q.bookings,money(q.cpb,c.currency)+' / booking'],['Won',q.wins,money(q.cpw,c.currency)+' / won'],['Feedback coverage',q.coverage==null?'—':Math.round(q.coverage)+'%',`${q.reported} reported / ${q.platformLeads} platform leads`]].map(([l,v,sub])=>`<section class="metric"><div class="metric-top">${l}</div><div class="metric-value">${q.records.length?v:'—'}</div><small class="cell-sub">${sub}</small></section>`).join('')}</div><div class="notice">${icon('info',15)}<span>Costs use spend only on days with confirmed feedback. Bookings ${c.wonImpliesBooked?'include won outcomes':'exclude won outcomes'}. ${q.days}/7 days covered. ${q.coverage>100?'Coverage exceeds 100%; review overlapping counts.':'Status counts should be mutually exclusive.'}</span></div><div class="content-two"><div class="stack"><section class="card section-pad"><div class="section-head"><h2>How lead quality is changing</h2><span class="badge neutral">Confirmed counts</span></div><div class="status-chart">${ds.map(d=>{const v=quality(c.id,[d]),max=Math.max(...ds.map(x=>quality(c.id,[x]).reported),1);return`<div class="status-chart-day"><div class="status-stack" aria-label="${d} Oct: ${v.reported} reported outcomes">${['none','junk','qualified','booked','won'].map(b=>`<i class="bucket-${b}" style="height:${v.buckets[b]/max*140}px" title="${b}: ${v.buckets[b]}"></i>`).join('')}</div><span>${d} Oct</span></div>`}).join('')}</div><div class="status-legend">${['qualified','booked','won','junk','none'].map(b=>`<span><i class="bucket-${b}"></i>${b==='none'?'Other':b[0].toUpperCase()+b.slice(1)}</span>`).join('')}</div></section><section class="card table-card"><div class="card-header"><h2>Outcomes by campaign</h2><span class="badge neutral">Ranked by bookings</span></div><div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Bookings</th><th>Won</th><th>Cost / booking</th><th>Coverage</th></tr></thead><tbody>${byCampaign.map(({cp,q})=>`<tr><td><a class="text-link" href="#/clients/${c.id}/campaigns/${cp.id}">${esc(cp.name)}</a></td><td>${q.records.length?q.bookings:'—'}</td><td>${q.records.length?q.wins:'—'}</td><td>${money(q.cpb,c.currency)}</td><td>${q.coverage==null?'—':Math.round(q.coverage)+'%'}</td></tr>`).join('')}</tbody></table></div></section><section class="card table-card"><div class="card-header"><h2>Cost per booking by branch</h2></div><div class="table-scroll"><table><thead><tr><th>Branch</th><th>Reported leads</th><th>Bookings</th><th>Cost / booking</th></tr></thead><tbody>${(configuredBranches(c.id).length?configuredBranches(c.id):[{code:'',label:'All'}]).map(b=>{const x=quality(c.id,ds,b.code?{branch:b.code}:{});return`<tr><td>${esc(b.label)}</td><td>${x.reported||'—'}</td><td>${x.records.length?x.bookings:'—'}</td><td>${money(x.cpb,c.currency)}</td></tr>`}).join('')}</tbody></table></div></section></div><div class="stack"><section class="card section-pad"><div class="section-head"><h2>Feedback health</h2><span class="badge ${q.last?'success':'warning'}">${q.last?'Up to date':'Missing'}</span></div><div class="definition-list"><div><span>Latest outcome date</span><strong>${q.last?fmtDate(q.last):'Not received'}</strong></div><div><span>Booking rate</span><strong>${pct(q.bookingRate)}</strong></div><div><span>Junk rate</span><strong>${pct(q.junkRate)}</strong></div><div><span>Reported outcomes</span><strong>${num(q.reported)}</strong></div></div><p class="subtext" style="margin-top:18px;line-height:1.7">Missing-feedback reminders go to Performance | CH every Monday at 10:00 IST in the production workflow.</p></section><section class="card section-pad"><div class="section-head"><h2>Paste & confirmation history</h2>${icon('history',15)}</div>${history.length?history.slice(0,6).map(h=>`<div class="history-entry"><strong>${h.rows} outcome rows confirmed</strong><p>${esc(h.source)} · ${esc(h.by)}</p><small>${timeLabel(h.date)}</small></div>`).join(''):'<div class="empty-state" style="padding:25px 5px">No submitted pastes yet.</div>'}<p class="subtext" style="font-size:10px;margin-top:15px">Raw pasted text is never included in this history, reports, PDFs, or exports.</p></section></div></div>`}
 function qualityReviewSnippet(c){const q=quality(c.id);return`<div class="review-outcomes"><div class="section-head"><h3>Client outcomes · last 7 days</h3><span class="badge neutral">Confirmed feedback</span></div><p>${q.records.length?`${q.bookings} bookings · ${q.wins} won · ${money(q.cpb,c.currency)} per booking. Feedback covers ${Math.round(q.coverage||0)}% of platform leads on ${q.days} reported days.`:'No confirmed lead-quality feedback is available. Recommendations have limited outcome context.'}</p><a class="text-link" href="#/clients/${c.id}/quality">Explore outcomes ${icon('arrow',11)}</a></div>`}
 function qualityRecommendations(c){const q=quality(c.id);if(!q.records.length)return[{title:'Ask the client for lead outcomes',priority:'p2',platform:'both',metric:'cost_per_booking',basis:'Feedback coverage · missing',action:'Request dated counts for qualified, booked and won outcomes. Paste the reply into Lead feedback and confirm the structured rows.',impact:'Assess meaningful outcomes alongside platform lead volume.'}];const branch= configuredBranches(c.id).map(b=>({...b,q:quality(c.id,undefined,{branch:b.code})})).filter(b=>b.q.cpb!=null).sort((a,b)=>a.q.cpb-b.q.cpb);return branch.length>1?[{title:'Compare booking efficiency across branches',priority:'p1',platform:'both',metric:'cost_per_booking',basis:`${branch[0].code} ${money(branch[0].q.cpb,c.currency)} · ${branch.at(-1).code} ${money(branch.at(-1).q.cpb,c.currency)} / booking`,action:'Review differences in booking quality and follow-up between branches before recommending a budget reallocation. Confirm comparable feedback coverage first.',impact:'Focus budget decisions on confirmed bookings.'}]:[]}
 function extraFlags(){const date=window.__LIVE?new Date(window.__LIVE.endDate+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'}):'22 Oct';const missing=clients().filter(c=>c.feedbackExpected&&!quality(c.id).last).map(c=>({id:'feedback-'+c.id,client:c.id,type:'feedback_missing',title:'Client outcome feedback is missing',description:window.__LIVE?'No confirmed lead outcomes are stored for this client yet. Add dated outcome counts before reading booking cost.':'No confirmed feedback in the sample period. Ask for dated outcome counts before assessing booking efficiency.',severity:'warn',audience:'Internal',date,label:'Feedback missing'}));if(window.__LIVE)return missing;return missing.concat([{id:'booking-a',client:'a',type:'cost_per_booking_up',title:'Review booking efficiency by branch',description:'Confirmed branch outcomes have different costs per booking. Check coverage and lead handling before shifting allocations. Illustrative signal.',severity:'warn',audience:'Internal',date:'22 Oct',label:'Booking cost'}])}
 function reportsPage(){let list=clients().filter(c=>(state.reportFilter!=='unsent'||!sent(c.id))&&(state.reportFilter!=='sent'||sent(c.id)));if(!list.some(c=>c.id===state.selectedReport))state.selectedReport=list[0]?.id||'a';const c=clientById(state.selectedReport),s=sent(c.id),enabled=clients().filter(c=>c.reportEnabled),done=enabled.filter(c=>sent(c.id)).length,dailyDone=enabled.filter(c=>sent(c.id,'daily')).length,weeklyDone=enabled.filter(c=>sent(c.id,'weekly')).length,text=reportText(c.id),allowed=safeText(text),audit=db.reportAudit.filter(a=>a.key===reportKey(c.id));return heading('Ready inside. Shared with care.','Copy the report, forward the PDF, then mark the client handoff.',`<button class="btn" data-action="go" data-value="settings/system">${icon('settings',13)}Report settings</button>`,'CLIENT REPORTS')+`<div class="notice">${icon('send',17)}<span><strong>Performance | CH is the only automated destination.</strong> Staff share reports to client WhatsApp groups manually. This is a sample workspace.</span></div><div class="queue-summary"><div class="stat-pill"><strong>${dailyDone}/${enabled.length}</strong><span>Daily sent · ${fmtDate(state.reportDate)}</span></div><div class="stat-pill"><strong>${weeklyDone}/${enabled.length}</strong><span>Weekly sent · ${reportDays('weekly')[0]}–${reportDays('weekly').at(-1)} Oct</span></div><div class="stat-pill"><strong>${enabled.length-done}</strong><span>${state.reportKind==='daily'?'Daily':'Weekly'} handoffs remaining</span></div><div class="stat-pill"><strong>Separate logs</strong><span>Daily & weekly handoffs</span></div></div><div class="filterbar"><div class="filter-left"><div class="segmented">${[['daily','Daily'],['weekly','Weekly']].map(([v,l])=>`<button class="${state.reportKind===v?'active':''}" data-action="v3-report-kind" data-value="${v}">${l}</button>`).join('')}</div>${picker(state.reportKind==='weekly'?'weeklyDate':'reportDate','Report date',state.reportKind==='weekly'?[['2026-10-18','12–18 Oct 2026'],['2026-10-11','5–11 Oct 2026']]:[['2026-10-22','22 Oct 2026'],['2026-10-21','21 Oct 2026'],['2026-10-20','20 Oct 2026']],'calendar','v3')}</div><div class="segmented">${[['all','All clients'],['unsent','Not yet sent'],['sent','Marked sent']].map(([v,l])=>`<button class="${state.reportFilter===v?'active':''}" data-action="v3-report-filter" data-value="${v}">${l}</button>`).join('')}</div></div><div class="telegram-layout"><section class="card"><div class="card-header"><h2>Client handoffs</h2><span class="date-label">${state.reportKind==='weekly'?`${reportDays()[0]}–${reportDays().at(-1)} Oct 2026`:fmtDate(state.reportDate)}</span></div>${list.length?list.map(x=>{const sx=sent(x.id);return`<button class="report-row ${c.id===x.id?'active':''}" data-action="v3-select-report" data-id="${x.id}">${avatar(x)}<span class="report-info"><strong>${esc(x.name)}</strong><small>${x.reportEnabled?(sx?`${esc(sx.by)} · ${timeLabel(sx.at)}`:'Ready internally · waiting for handoff'):'Reports disabled'}</small></span><span class="badge ${sx?'success':x.reportEnabled?'warning':'neutral'}">${sx?'Sent':x.reportEnabled?'Not yet':'Disabled'}</span>${icon('chevron',12)}</button>`}).join(''):'<div class="empty-state">No clients in this view.</div>'}<div class="table-footer">Text and PDF share one status per report period. Daily and weekly are tracked separately.</div></section><div class="stack">${list.length?`<section class="card"><div class="card-header"><div><h2>WhatsApp-ready report</h2><p>${esc(c.whatsappGroup)} · preview</p></div><span class="badge neutral">${state.reportKind==='weekly'?'Weekly':'Daily'}</span></div><div class="message-preview"><div class="telegram-bubble whatsapp-bubble"><pre>${esc(text)}</pre><div class="time">Client-ready copy</div></div></div><div class="pdf-attachment">${icon('file',25)}<div><strong>${esc(c.name)} · ${state.reportKind==='weekly'?'Weekly':'Daily'} ad report.pdf</strong><small>${state.reportKind==='weekly'?`${reportDays()[0]}–${reportDays().at(-1)} Oct`:fmtDate(state.reportDate)} · A4 · campaign & ad-set detail</small></div><button class="icon-btn" data-action="v3-download" data-id="${c.id}" aria-label="Download PDF">${icon('download',17)}</button></div><div class="preview-footer">${!allowed?'<div class="error-banner">Copy is blocked: the report contains a restricted internal term. Update the client label or deny-list configuration.</div>':''}<div class="report-card-actions"><button class="btn primary" data-action="v3-copy" data-id="${c.id}" ${!allowed?'disabled':''}>${icon('copy',13)}Copy for WhatsApp</button><button class="btn" data-action="v3-sent" data-id="${c.id}" ${!canEdit()||!c.reportEnabled?'disabled':''}>${icon(s?'checkCircle':'check',13)}${s?'Unmark as sent':'Mark as sent to client'}</button><button class="btn" data-action="v3-generate" data-id="${c.id}" ${!canEdit()?'disabled':''}>${icon('file',13)}Generate PDF</button><button class="btn ghost" data-action="v3-resend" data-id="${c.id}" ${!isAdmin()?'disabled':''}>${icon('refresh',12)}Resend internally</button></div><p class="subtext" style="margin-top:13px;line-height:1.7">${s?`Marked by ${esc(s.by)} · ${timeLabel(s.at)}`:'Copy and download do not change the sent status.'} AI client notes are off in v1.</p>${audit.length?`<button class="text-link" style="margin-top:8px" data-action="v3-audit" data-id="${c.id}">View handoff history (${audit.length}) ${icon('history',12)}</button>`:''}</div></section>`:''}<section class="help-card"><h3>The daily team routine</h3><p>1. Review the report.<br>2. Copy the text and download the PDF.<br>3. Share both in the client’s WhatsApp group.<br>4. Mark as sent and add their outcome feedback.</p></section></div></div>`+bottomNote()}

 function redact(raw,id){let s=String(raw||'');const protectedDates=[];s=s.replace(/\b\d{4}-\d{2}-\d{2}\b/g,m=>{protectedDates.push(m);return '__DATE'+(protectedDates.length-1)+'__'});s=s.replace(/https?:\/\/\S+|www\.\S+/gi,' [URL] ').replace(/[\w.+-]+@[\w.-]+\.[a-z]{2,}/gi,' [EMAIL] ').replace(/(?:\+?\d[\s().-]*){7,}/g,' [PHONE] ');s=s.replace(/^[ \t]*\[?(\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}),?[ \t]+\d{1,2}[:.]\d{2}(?:[:.]\d{2})?(?:[ \t]*[ap]\.?m\.?)?\]?[ \t]*[-–]?[ \t]*[^:\n]+:[ \t]*/gim,(_,date)=>date+' [NAME]: ');const allow=new Set(['jan','january','feb','february','mar','march','apr','april','may','jun','june','jul','july','aug','august','sep','sept','september','oct','october','nov','november','dec','december','st','nd','rd','th','today','yesterday','leads','lead','total','date','branch','campaign','ad','set','group','phone','name','email','url','north','south','all','and','on','for','at','to','of','response','responses','meeting','appointments']);for(const st of statuses(id))for(const w of (st.label+' '+st.synonyms).toLowerCase().match(/[a-z]+/g)||[])allow.add(w);for(const r of rules(id))for(const w of (r.code+' '+r.label+' '+r.aliases).toLowerCase().match(/[a-z]+/g)||[])allow.add(w);for(const cp of campaigns(id,undefined,'all'))for(const w of cp.name.toLowerCase().match(/[a-z]+/g)||[])allow.add(w);return s.replace(/__DATE\d+__|[\p{L}][\p{L}\p{M}'’-]*/gu,w=>/^__DATE\d+__$/.test(w)||allow.has(w.toLowerCase())?w:'[NAME]').replace(/(?:\[NAME\]\s*){2,}/g,'[NAME] ').replace(/__DATE(\d+)__/g,(_,i)=>protectedDates[Number(i)]).trim()}
 function parseFeedback(text,id){const rows=[],warnings=[];let currentDate=sampleDate;const lines=text.split(/\n/).map(x=>x.trim()).filter(Boolean);const sts=statuses(id);for(const [li,line] of lines.entries()){
   const lineDate=feedbackDate(line);if(lineDate)currentDate=lineDate;else if(/yesterday/i.test(line))currentDate=shiftIso(feedbackMax(),-1);else if(/today/i.test(line))currentDate=feedbackMax();else if(li===0)warnings.push('A date was not found on the first line. Verify the default date in the grid.');
   const branch=configuredBranches(id).find(b=>line.toLowerCase().includes(b.code.toLowerCase())||line.toLowerCase().includes(b.label.toLowerCase())||rules(id).some(r=>r.code===b.code&&String(r.aliases||'').split(',').some(a=>a.trim()&&line.toLowerCase().includes(a.trim().toLowerCase()))));
   const cp=campaigns(id,undefined,'all').find(c=>line.toLowerCase().includes(c.name.toLowerCase()));let work=line.replace(/\b\d{4}-\d{2}-\d{2}\b/g,'').replace(/\b\d{1,2}[\/.]\d{1,2}[\/.]\d{2,4}\b/g,'').replace(/\b\d{1,2}(?:st|nd|rd|th)?\s*(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?(?:,?\s+\d{4})?/gi,'').replace(/\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d{1,2}(?:st|nd|rd|th)?(?:,?\s+\d{4})?/gi,'');let found=0;
   const aliases=sts.flatMap(st=>[st.label,...st.synonyms.split(',')].map(a=>({st,alias:a.trim()}))).filter(x=>x.alias).sort((a,b)=>b.alias.length-a.alias.length);
   const consumed=[];for(const {st,alias} of aliases){const pat=alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\s+/g,'\\s+');const rx=new RegExp('(?:\\b(\\d+)\\s+'+pat+'\\b|\\b'+pat+'\\s*[:=-]?\\s*(\\d+)\\b)','gi');for(const m of work.matchAll(rx)){if(consumed.some(([a,b])=>m.index<b&&m.index+m[0].length>a))continue;consumed.push([m.index,m.index+m[0].length]);rows.push({client:id,date:currentDate,branch:branch?.code||'',campaign:cp?.id||'',adset:'',status:st.id,count:Number(m[1]??m[2]),confidence:lineDate ? 0.98 : 0.7,sourceLine:li+1});found++;}}
   if(!found)warnings.push(`Line ${li+1} could not be parsed. Add the missing counts manually.`);
   const residue=consumed.reduce((t,[a,b])=>t.slice(0,a)+' '.repeat(b-a)+t.slice(b),work);if(/\d/.test(residue))warnings.push(`Line ${li+1} contains unmatched numbers. Check the grid against the redacted text.`);
 }return {rows,warnings:[...new Set(warnings)]};}
 const previewCounts=()=>state.feedbackRows.reduce((n,r)=>{const old=db.leadRecords.find(x=>recordKey(x)===recordKey(r));old?n.updates++:n.fresh++;return n},{fresh:0,updates:0});
 function feedbackPage(){if(!clients().some(x=>x.id===state.feedbackClient)&&clients().length){state.feedbackClient=clients()[0].id;state.feedbackRows=state.feedbackRows.map(r=>({...r,client:state.feedbackClient}))}const c=clientById(state.feedbackClient),counts=previewCounts();return heading('Close the loop on every lead.','Paste client outcomes, review the structured counts, then confirm.',`<button class="btn" data-action="v3-next-client">Next client ${icon('arrow',13)}</button>`,'LEAD FEEDBACK')+`<div class="feedback-steps"><span class="active"><b>1</b>Paste & redact</span><i></i><span class="${state.feedbackRows.length?'active':''}"><b>2</b>Review & correct</span><i></i><span><b>3</b>Confirm outcomes</span></div><div class="feedback-layout"><section class="card section-pad"><div class="section-head"><h2>Client feedback</h2><span class="badge neutral">WhatsApp paste</span></div><label class="field"><span>Client</span><select data-v3="feedbackClient" aria-label="Feedback client">${clients().map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="segmented" style="margin:18px 0 12px"><button data-action="v3-feedback-mode" data-value="paste" class="${state.feedbackMode==='paste'?'active':''}">Paste reply</button><button data-action="v3-feedback-mode" data-value="manual" class="${state.feedbackMode==='manual'?'active':''}">Manual grid</button></div>${state.feedbackMode==='paste'?`<label class="field"><span>Client’s reply</span><textarea id="feedback-paste" class="paste-box" placeholder="22 Oct: 5 responded, 3 not qualified, 2 booked, 1 no budget, 1 won" ${!canEdit()?'disabled':''}>${esc(state.feedbackRaw)}</textarea><small>One day or a whole week. Enter aggregate counts, with each lead in one current status.</small></label><div style="display:flex;gap:8px;margin-top:12px"><button class="btn primary" data-action="v3-parse" ${!canEdit()?'disabled':''}>${icon('shield',13)}Redact & preview</button><button class="btn ghost" data-action="v3-use-example" ${!canEdit()?'disabled':''}>Use sample reply</button></div>`:`<div class="note-box">${icon('edit',15)}Add outcome rows directly. Manual entry is always available, including when a production parser reaches its cost cap.</div><button class="btn" style="margin-top:15px" data-action="v3-add-row" ${!canEdit()?'disabled':''}>${icon('plus',13)}Add outcome row</button>`}<div class="privacy-note">${icon('lock',15)}<span>Local UI preview. No text is sent to a model. Raw pasted text is held only in this unsaved session and is not stored with confirmed counts.</span></div>${state.feedbackRedacted?`<div class="redacted-box"><h3>Exact redacted text</h3><pre>${esc(state.feedbackRedacted)}</pre><small>Unknown words are conservatively masked. Review missing context manually.</small></div>`:''}<a class="text-link" style="margin-top:20px" href="#/clients/${c.id}/quality">View ${esc(c.name)} lead quality ${icon('arrow',12)}</a></section><section class="card feedback-preview"><div class="card-header"><div><h2>Review before saving</h2><p>${state.feedbackRows.length?`${counts.fresh} new · ${counts.updates} updates. Existing counts are replaced, never added twice.`:'Parsed outcomes appear here. Nothing saves automatically.'}</p></div><button class="btn small" data-action="v3-add-row" ${!canEdit()?'disabled':''}>${icon('plus',12)}Add row</button></div>${state.feedbackWarnings.length?`<div class="feedback-warning">${icon('warning',15)}<div>${state.feedbackWarnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div></div>`:''}${state.feedbackRows.length?`<div class="table-scroll"><table class="feedback-grid"><thead><tr><th>Date</th><th>Status</th><th>Count</th><th>Branch</th><th>Campaign / ad set</th><th>Change</th><th></th></tr></thead><tbody>${state.feedbackRows.map((r,i)=>{const old=db.leadRecords.find(x=>recordKey(x)===recordKey(r));return`<tr class="${r.confidence<.85?'needs-review':''}"><td><input type="date" value="${r.date}" data-feedback-field="date" data-index="${i}" min="${feedbackMin()}" max="${feedbackMax()}" aria-label="Row ${i+1} date"/></td><td><select data-feedback-field="status" data-index="${i}" aria-label="Row ${i+1} status">${statuses(c.id).map(s=>`<option value="${s.id}" ${r.status===s.id?'selected':''}>${esc(s.label)}</option>`).join('')}</select></td><td><input type="number" min="0" max="100000" step="1" value="${r.count}" data-feedback-field="count" data-index="${i}" aria-label="Row ${i+1} count"/></td><td><select data-feedback-field="branch" data-index="${i}" aria-label="Row ${i+1} branch"><option value="">All / untagged</option>${configuredBranches(c.id).map(b=>`<option value="${b.code}" ${r.branch===b.code?'selected':''}>${esc(b.code)}</option>`).join('')}</select></td><td><select data-feedback-field="campaign" data-index="${i}" aria-label="Row ${i+1} campaign"><option value="">Client-level</option>${campaigns(c.id,undefined,'all').map(cp=>`<option value="${cp.id}" ${r.campaign===cp.id?'selected':''}>${esc(cp.name)}</option>`).join('')}</select><select data-feedback-field="adset" data-index="${i}" aria-label="Row ${i+1} ad set"><option value="">No ad-set tag</option>${r.campaign?adsets(c.id,r.campaign).map(a=>`<option value="${a.id}" ${r.adset===a.id?'selected':''}>${esc(a.name)}</option>`).join(''):''}</select></td><td><span class="badge ${old?'warning':'success'}">${old?`${old.count} → ${r.count}`:'New'}</span>${r.confidence<.85?'<small class="cell-sub">Check date</small>':''}</td><td><button class="icon-btn" data-action="v3-remove-row" data-index="${i}" aria-label="Remove row ${i+1}">${icon('close',12)}</button></td></tr>`}).join('')}</tbody></table></div><div class="feedback-confirm"><label><input type="checkbox" data-v3-confirm ${state.feedbackConfirmed?'checked':''} ${!canEdit()?'disabled':''}/>I checked dates, counts and campaign / branch tags.</label><button class="btn primary" data-action="v3-confirm-feedback" ${!state.feedbackConfirmed||!canEdit()?'disabled':''}>${icon('check',14)}Confirm & save ${state.feedbackRows.length} rows</button></div>`:`<div class="empty-state" style="padding:80px 25px">${icon('message',33)}<h3>A little feedback. A better picture.</h3><p>Try the sample reply, or start with the manual grid.</p></div>`}</section></div>`+bottomNote()}
 function clientConfig(c){return`<div class="settings-layout"><div class="stack"><form class="card section-pad" data-form="v3-client" data-id="${c.id}"><div class="section-head"><h2>Client & reporting</h2><span class="badge neutral">${c.currency}</span></div><fieldset ${!isAdmin()?'disabled':''} class="plain-fieldset"><div class="form-grid"><label class="field"><span>Client name</span><input name="name" value="${esc(c.name)}" required maxlength="60"/></label><label class="field"><span>Monthly budget (${c.currency})</span><input name="budget" type="number" min="1" value="${c.budget}" required/></label><label class="field full"><span>WhatsApp group label</span><input name="whatsappGroup" value="${esc(c.whatsappGroup)}" maxlength="80" required/><small>Internal reference only. Do not enter a phone number or group invite link.</small></label><label class="field full"><span>Review context</span><textarea name="context">${esc(c.context)}</textarea></label></div>${[['reportEnabled','Daily reports','Prepare a client report in the internal staff group.'],['pdfWeekly','Weekly PDF','Every Monday for the previous Monday–Sunday.'],['pdfDaily','Daily PDF','Include a PDF with the daily report.'],['feedbackExpected','Client outcome feedback','Include this client in missing-feedback reminders.'],['wonImpliesBooked','Won outcomes imply a booking','Include won counts in the booking denominator.'],['ai','Daily AI review','Generate staff-facing recommendations.'],['aiLevelSummaries','Campaign & ad-set summaries','Short, cached summaries for staff.']].map(([key,l,d])=>`<div class="switch-row"><div><strong>${l}</strong><p>${d}</p></div><input type="checkbox" name="${key}" ${c[key]?'checked':''} aria-label="${l}"/></div>`).join('')}<div class="form-actions"><button type="submit" class="btn primary">Save client settings</button></div></fieldset></form><form class="card section-pad" data-form="v3-branches" data-id="${c.id}"><div class="section-head"><h2>Branch rules</h2><button type="button" class="btn small" data-action="v3-add-branch" data-id="${c.id}" ${!isAdmin()?'disabled':''}>${icon('plus',12)}Add rule</button></div><p class="subtext" style="margin-bottom:16px">Match campaign, ad-set or ad names. Clients without rules use “All”.</p><fieldset ${!isAdmin()?'disabled':''} class="plain-fieldset"><div class="branch-rule-list">${rules(c.id).map((r,i)=>`<div class="branch-rule"><label class="field"><span>Code</span><input name="code_${i}" value="${esc(r.code)}" required/></label><label class="field"><span>Branch label</span><input name="label_${i}" value="${esc(r.label)}" required/></label><label class="field"><span>Match at</span><select name="level_${i}">${['campaign','adset','ad'].map(l=>`<option value="${l}" ${r.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Rule</span><select name="type_${i}"><option value="prefix" ${r.type==='prefix'?'selected':''}>Prefix</option><option value="regex" ${r.type==='regex'?'selected':''}>Regex</option></select></label><label class="field"><span>Pattern</span><input name="match_${i}" value="${esc(r.match)}" required/></label><label class="field"><span>Aliases</span><input name="aliases_${i}" value="${esc(r.aliases||'')}"/></label><button class="btn small danger" type="button" data-action="v3-remove-branch" data-id="${c.id}" data-index="${i}">Remove</button></div>`).join('')||'<div class="note-box">No branch rules. All spend stays in one group.</div>'}</div><div class="form-actions"><button type="submit" class="btn primary">Save branch rules</button></div></fieldset></form></div><div class="stack"><section class="help-card"><h3>One delivery destination.</h3><p>All automated text and PDF posts go to Performance | CH. Staff forward the finished report into the client’s WhatsApp group.</p><p>No client Telegram chat IDs or WhatsApp API connection are needed.</p></section><section class="card section-pad"><h2>Lead statuses</h2><p class="subtext" style="line-height:1.8;margin:10px 0 16px">Map the client’s wording to qualified, booked, won, junk, or other outcome buckets.</p><button class="btn" data-action="v3-open-statuses" data-id="${c.id}">Configure lead statuses ${icon('arrow',12)}</button></section></div></div>`}
 function settingsClients(){return`<section class="card table-card"><div class="card-header"><h2>Client reporting preferences</h2><span class="badge neutral">${clients().length} clients</span></div><div class="table-scroll"><table><thead><tr><th>Client</th><th>WhatsApp group label</th><th>Reports</th><th>Weekly PDF</th><th>Daily PDF</th><th>Feedback expected</th><th></th></tr></thead><tbody>${clients().map(c=>`<tr><td><div class="client-name-cell">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${c.currency} · ${esc(c.sector)}</small></div></div></td><td>${esc(c.whatsappGroup)}</td>${['reportEnabled','pdfWeekly','pdfDaily','feedbackExpected'].map(key=>`<td><button class="switch ${c[key]?'on':''}" role="switch" aria-checked="${c[key]}" aria-label="${esc(c.name)} ${key}" data-action="v3-client-toggle" data-id="${c.id}" data-value="${key}" ${!isAdmin()?'disabled':''}></button></td>`).join('')}<td><a class="btn small" href="#/clients/${c.id}/configuration">Configure ${icon('chevron',11)}</a></td></tr>`).join('')}</tbody></table></div></section><div class="note-box" style="margin-top:20px">${icon('info',15)}Preferences are saved locally in this prototype. Only the production worker schedules and posts internal reports.</div>`}
 function statusSettings(){const c=clientById(state.statusClient),list=statuses(c.id);return`<div class="section-head"><div><h2>Lead-status vocabulary</h2><p class="subtext">Client wording in. Consistent outcome buckets out.</p></div><label class="select-wrap"><select data-v3="statusClient" aria-label="Status configuration client">${clients().map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><form class="card section-pad" data-form="v3-statuses" data-id="${c.id}"><fieldset class="plain-fieldset" ${!isAdmin()?'disabled':''}><div class="table-scroll"><table><thead><tr><th>Status label</th><th>Outcome bucket</th><th>Synonyms · comma separated</th><th></th></tr></thead><tbody>${list.map((s,i)=>`<tr><td><input class="config-input" name="label_${i}" value="${esc(s.label)}" aria-label="Status ${i+1} label" required/></td><td><select class="config-input" name="bucket_${i}" aria-label="Status ${i+1} bucket">${['qualified','booked','won','junk','none'].map(b=>`<option value="${b}" ${s.bucket===b?'selected':''}>${b}</option>`).join('')}</select></td><td><input class="config-input" name="synonyms_${i}" value="${esc(s.synonyms)}" aria-label="Status ${i+1} synonyms" style="min-width:240px"/></td><td><button class="icon-btn" type="button" data-action="v3-remove-status" data-id="${c.id}" data-index="${i}" aria-label="Remove status ${i+1}">${icon('close',12)}</button></td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn" type="button" data-action="v3-add-status" data-id="${c.id}">${icon('plus',13)}Add status</button><button class="btn primary" type="submit">Save status vocabulary</button></div></fieldset></form><div class="note-box" style="margin-top:20px">${icon('info',15)}Qualified cost uses qualified + booked + won. Booking cost includes won outcomes by default. “None” statuses count toward feedback coverage but not qualified outcomes.</div>`}
 function aiSettings(){const purpose=state.aiPurpose,entry=purpose==='review'?{settings:db.settings,version:db.settingsVersion,versions:db.versions}:db.aiPurposes[purpose],s=entry.settings;return`<div class="purpose-tabs">${[['review','Performance reviews','spark'],['feedback_parser','Feedback parser','message'],['level_summary','Level summaries','grid']].map(([v,l,i])=>`<button class="${purpose===v?'active':''}" data-action="v3-ai-purpose" data-value="${v}">${icon(i,15)}${l}</button>`).join('')}</div><div class="settings-layout"><form class="card section-pad" data-form="v3-ai"><div class="section-head"><h2>${purpose==='review'?'Daily review configuration':purpose==='feedback_parser'?'Feedback parser configuration':'Campaign & ad-set summaries'}</h2><span class="badge success">Version ${entry.version} · active</span></div><div class="form-grid">${[['model','Model'],['promptVersion','Prompt version'],['temperature','Temperature'],['inputTokens','Max input tokens'],['outputTokens','Max output tokens'],['inputPrice','Input price / 1M · USD'],['outputPrice','Output price / 1M · USD']].map(([k,l])=>`<label class="field"><span>${l}</span><input name="${k}" value="${esc(s[k])}" ${['temperature','inputTokens','outputTokens','inputPrice','outputPrice'].includes(k)?'type="number" min="0" step="any"':''} ${purpose==='feedback_parser'&&k==='temperature'?'readonly':''} required/></label>`).join('')}<label class="field full"><span>System prompt</span><textarea name="systemPrompt" class="code" required>${esc(s.systemPrompt)}</textarea></label><label class="field full"><span>User prompt</span><textarea name="userPrompt" class="code" required>${esc(s.userPrompt)}</textarea></label><label class="field full"><span>Output shape · sample JSON</span><textarea name="schema" class="code" required>${esc(s.schema)}</textarea></label><label class="field full"><span>Change note</span><input name="changeNote" placeholder="What changed in this purpose’s configuration?" required/></label></div><div class="form-actions"><button type="button" class="btn" data-action="v3-test-purpose">Test preview</button><button type="submit" class="btn primary">Save new version</button></div></form><div class="stack"><section class="card section-pad"><div class="section-head"><h2>Shared daily cost allowance</h2><span class="badge neutral">Sample</span></div><div class="metric-value">$0.43 <small>/ $2.00 cap</small></div><div class="usage-breakdown"><div><span>Reviews</span><strong>$0.38</strong></div><div><span>Feedback parser</span><strong>$0.02</strong></div><div><span>Level summaries</span><strong>$0.03</strong></div><div><span>PDF reports</span><strong>$0.00 · no AI</strong></div></div><div class="note-box" style="margin-top:18px">At the cost cap, reviews skip and feedback entry remains available through the manual grid.</div></section><section class="card section-pad"><div class="section-head"><h2>Purpose version history</h2></div><div class="version-row"><span class="badge success">v${entry.version}</span><div class="version-info">${esc(s.promptVersion)}<small>Active · ${purpose}</small></div></div>${entry.versions.slice().reverse().map(v=>`<div class="version-row"><span class="badge neutral">v${v.version}</span><div class="version-info">${esc(v.settings.promptVersion)}<small>${esc(v.note||'Previous configuration')}</small></div><button class="text-link" data-action="v3-purpose-diff" data-index="${v.version}">Compare</button></div>`).join('')||'<p class="subtext">Each purpose keeps its own active version.</p>'}</section><section class="help-card"><h3>Only redacted counts reach the parser.</h3><p>Names, phone numbers, email addresses and links are stripped in code first. Staff review the exact redacted text and confirm the parsed outcome rows.</p></section></div></div>`}
 function systemSettings(){return`<div class="settings-layout"><div class="stack"><form class="card section-pad" data-form="v3-system"><div class="section-head"><h2>Report controls</h2><span class="badge neutral">Local preview</span></div><fieldset ${!isAdmin()?'disabled':''} class="plain-fieldset"><div class="form-grid"><label class="field full"><span>Additional client-copy blocked terms</span><textarea name="denylist" placeholder="Comma-separated terms">${esc(db.systemV3.denylist)}</textarea><small>Checked before copy and PDF generation, alongside the built-in internal-tool deny-list.</small></label><label class="field"><span>Ad cards per PDF page</span><select name="cardsPerPage">${[2,4,6].map(n=>`<option value="${n}" ${db.systemV3.cardsPerPage===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Missing feedback after · days</span><input name="missingDays" value="${db.systemV3.missingDays}" type="number" min="1" max="30" required/></label><label class="field"><span>Report mode · server-managed</span><input value="Internal" disabled/></label><label class="field"><span>PDF format</span><input value="A4 portrait · embedded fonts" disabled/></label></div><div class="form-actions"><button class="btn primary" type="submit">Save report preferences</button></div></fieldset></form><form class="card section-pad" data-form="thresholds"><div class="section-head"><h2>Performance thresholds</h2></div><fieldset ${!isAdmin()?'disabled':''} class="plain-fieldset"><div class="form-grid">${[['spendSpike','Spend spike multiplier',1.5],['cpaUp','CPA increase multiplier',1.3],['pacingOver','Over pacing %',115],['pacingUnder','Under pacing %',80],['staleHours','Stale data · hours',3],['bookingUp','Cost per booking multiplier',1.3],['junkRise','Junk share increase · points',5]].map(([k,l,v])=>`<label class="field"><span>${l}</span><input name="${k}" value="${db.thresholds[k]??v}" type="number" min="0" step="0.1" required/></label>`).join('')}</div><div class="form-actions"><button class="btn primary" type="submit">Save thresholds</button></div></fieldset></form></div><div class="stack"><section class="card section-pad"><div class="section-head"><h2>Internal reporting schedule</h2>${icon('clock',15)}</div><div class="definition-list">${[['Daily reviews','07:30 IST'],['Daily text reports','09:00 IST'],['Weekly PDF','Monday · 09:00 IST'],['Missing-feedback reminder','Monday · 10:00 IST'],['Heartbeat check','09:15 IST'],['Only destination','Performance | CH'],['Alternative server mode','Dry run'],['Client notes','Off · v1.1']].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="note-box" style="margin-top:20px">These are the planned worker schedules. The UI preview does not send messages or run background jobs.</div></section><section class="help-card"><h3>Fresh data first.</h3><p>Production skips reviews and PDFs when data is stale. A PDF failure does not block the text report.</p><p>The internal pilot runs before staff start sharing reports with clients.</p></section></div></div>`}

 // HTTPS uses SHA-256. The local HTTP preview uses a deterministic non-security cache key.
 async function reportHash(serial){if(globalThis.crypto?.subtle){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(serial)))).map(b=>b.toString(16).padStart(2,'0')).join('')}let hash=14695981039346656037n;for(const b of new TextEncoder().encode(serial)){hash^=BigInt(b);hash=BigInt.asUintN(64,hash*1099511628211n)}return 'sample-'+hash.toString(16)+'-'+serial.length}
 let currentPdfUrl=null;
 const pdfCache=new Map();
 function buildReportModel(id,ds,kind='custom'){const c=clientById(id),m=aggregate(clientAccounts(id),ds),prev=aggregate(clientAccounts(id),ds.map(d=>typeof d==='string'?shiftDay(d,-ds.length):d-ds.length)),q=quality(id,ds);const cps=campaigns(id,ds,'all').map(cp=>({...cp,previous:campaign(id,cp.id,ds.map(d=>typeof d==='string'?shiftDay(d,-ds.length):d-ds.length)),quality:quality(id,ds,{campaign:cp.id}),adsets:adsets(id,cp.id,ds).map(as=>({...as,previous:adset(id,as.id,ds.map(d=>typeof d==='string'?shiftDay(d,-ds.length):d-ds.length)),quality:quality(id,ds,{adset:as.id}),ads:ads(id,as.id,ds)}))}));const branches=[...new Set(cps.map(cp=>cp.branch))].map(code=>({code:code||'All',name:configuredBranches(id).find(b=>b.code===code)?.label||code||'All',...sumMetrics(cps.filter(cp=>cp.branch===code)),quality:quality(id,ds,{branch:code})}));return{clientName:c.name,currency:c.currency,period:ds.length===1?fmtDate(isoDay(ds[0])):`${fmtDate(isoDay(ds[0]))} – ${fmtDate(isoDay(ds.at(-1)))}`,kind,days:ds,metrics:m,previous:prev,quality:{...q,records:undefined},platforms:['meta','google'].map(p=>({name:p==='meta'?'Meta Ads':'Google Ads',...aggregate(clientAccounts(id).filter(a=>a.platform===p),ds)})),branches,campaigns:cps,cardsPerPage:Math.min(6,db.systemV3.cardsPerPage),sample:true,templateVersion:4};}
 async function downloadPdf(id,ds,kind='custom',force=false){const version=state.interactionVersion;const c=clientById(id),model=buildReportModel(id,ds,kind);if(!model.metrics.spend){toast('PDF skipped: this period has zero spend.');return}const strings=[model.clientName,...model.branches.flatMap(b=>[b.name,b.code]),...model.campaigns.flatMap(cp=>[cp.name,cp.branch,...cp.adsets.flatMap(a=>[a.name,a.branch,...a.ads.flatMap(ad=>[ad.name,ad.type,ad.branch])])])];if(strings.some(s=>!safeText(s))){toast('PDF blocked: a report label contains a restricted internal term.');return}const serial=JSON.stringify(model),hash=await reportHash(serial);if(version!==state.interactionVersion)return;let found=db.pdfHistory.find(p=>p.hash===hash&&p.current);toast(found&&!force?'Opening the stored report PDF…':'Generating the client report PDF…');try{let bytes=pdfCache.get(hash);if(!bytes||force){bytes=await createReportPdf(model);pdfCache.set(hash,bytes)}if(version!==state.interactionVersion)return;if(!found||force){const previous=db.pdfHistory.filter(p=>p.client===id&&p.period===model.period);previous.forEach(p=>p.current=false);found={id:hash,hash,client:id,period:model.period,kind,revision:(previous.at(-1)?.revision||0)+1,current:true,at:new Date().toISOString(),adCount:model.campaigns.flatMap(c=>c.adsets.flatMap(a=>a.ads)).length};db.pdfHistory.push(found);persist()}if(currentPdfUrl?.startsWith('blob:'))URL.revokeObjectURL(currentPdfUrl);const pdfBlob=new Blob([bytes],{type:'application/pdf'});currentPdfUrl=URL.createObjectURL(pdfBlob);if(version!==state.interactionVersion)return;const filename=`${c.name.replace(/[^a-z0-9-]/gi,'_')}_Ad_Report_${isoDay(ds[0])}_${isoDay(ds.at(-1))}.pdf`;fetch('/api/pdf',{method:'POST',headers:{'x-client':id,'x-pdf-id':hash,'x-filename':encodeURIComponent(filename)},body:pdfBlob}).catch(()=>{});modal('Your report is ready',`<div class="pdf-ready">${icon('file',34)}<h3>${esc(c.name)} · Ad report</h3><p>${esc(model.period)} · A4 PDF · revision ${found.revision}</p></div><div class="note-box" style="margin-top:20px">Stored on this server. Downloading does not mark the client handoff as sent.</div>`,`<button class="btn" data-action="close">Done</button><a class="btn" href="${currentPdfUrl}" target="_blank" rel="noopener">Open PDF</a><a class="btn primary" href="${currentPdfUrl}" download="${filename}">${icon('download',14)}Download PDF</a>`);toast(`Report PDF stored · revision ${found.revision}.`)}catch(error){if(version!==state.interactionVersion)return;toast('The PDF could not be generated. Your report text is still available.');console.error('Sample PDF generation failed',error?.message)}}
 function generateModal(id){modal('Generate a client report',`<form id="v3-generate-form" data-form="v3-pdf" data-id="${id}"><p>${esc(clientById(id).name)} · ${window.__LIVE?'choose the dates; the report opens on Reports & PDFs, ready to download.':'choose a range from the sample data.'}</p><div class="form-grid" style="margin-top:18px"><label class="field"><span>Period start</span><input type="date" name="start" min="${window.__LIVE?shiftIso(window.__LIVE.endDate,-44):'2026-10-01'}" max="${window.__LIVE?window.__LIVE.endDate:'2026-10-22'}" value="${window.__LIVE?shiftIso(window.__LIVE.endDate,-6):'2026-10-16'}" required/></label><label class="field"><span>Period end</span><input type="date" name="end" min="${window.__LIVE?shiftIso(window.__LIVE.endDate,-44):'2026-10-01'}" max="${window.__LIVE?window.__LIVE.endDate:'2026-10-22'}" value="${window.__LIVE?window.__LIVE.endDate:'2026-10-22'}" required/></label></div><label class="check-label" style="margin-top:17px"><input type="checkbox" name="force"/>Force a new revision if the same report exists</label><div class="note-box" style="margin-top:17px">The downloaded A4 PDF mirrors the campaign → ad set → ad structure. It contains sample metrics and confirmed aggregate feedback only.</div></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="v3-generate-form">${icon('download',13)}Generate & download</button>`)}
 function blankRow(){return{client:state.feedbackClient,date:sampleDate,status:statuses(state.feedbackClient)[0].id,count:0,branch:'',campaign:'',adset:'',confidence:1}}
 function resetFeedback(){state.feedbackRows=[];state.feedbackRedacted='';state.feedbackWarnings=[];state.feedbackRaw='';state.feedbackConfirmed=false;}
 async function handleAction(el){const {action,id,value,index,kind,date}=el.dataset;switch(action){
  case'v3-open-report':state.selectedReport=id;go('reports');break;
  case'v3-select-report':state.selectedReport=id;render();break;
  case'v3-select-filter':state[el.dataset.key]=value;render();break;
  case'v3-report-kind':state.reportKind=value;render();break;
  case'v3-report-filter':state.reportFilter=value;render();break;
  case'v3-copy':{const version=state.interactionVersion,text=reportText(id,kind||state.reportKind,date);if(!safeText(text)){toast('Copy blocked by the client-copy check.');return}try{await navigator.clipboard.writeText(text);if(version!==state.interactionVersion)return;fetch('/api/outbox',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({client:id,kind:kind||state.reportKind||'daily',text})}).catch(()=>{});toast('Exact report text copied. The same text is in the internal outbox. Handoff status is unchanged.')}catch{if(version!==state.interactionVersion)return;modal('Copy for WhatsApp',`<textarea readonly class="inline-edit" style="height:260px" aria-label="Copy-ready report">${esc(text)}</textarea><p style="margin-top:12px">Select the full text and copy it. Mark as sent after sharing.</p>`)}break}
  case'v3-sent':{if(!canEdit()||!clientById(id).reportEnabled)return;const k=reportKey(id,kind||state.reportKind,date),old=db.reportSent[k],by=(window.__USER?.name||'Performance team'),at=new Date().toISOString();if(old)delete db.reportSent[k];else db.reportSent[k]={by,at};db.reportAudit.push({key:k,by,at,action:old?'Unmarked as sent':'Marked as sent',previous:old||null});persist();render();toast(old?'Handoff unmarked. The change is recorded.':'Marked as sent. Who and when are stored. Nothing was posted to a client group.');break}
  case'v3-audit':modal('Client handoff history',db.reportAudit.filter(x=>x.key===reportKey(id)).slice().reverse().map(x=>`<div class="history-entry"><strong>${x.action}</strong><p>${esc(x.by)} · ${timeLabel(x.at)}</p></div>`).join(''));break;
  case'v3-queue-internal':{if(!isAdmin())return;const text=reportText(id);if(!safeText(text)){toast('Copy blocked by the client-copy check.');return}const response=await fetch('/api/outbox',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({client:id,kind:'resend',text})});const result=await response.json().catch(()=>({}));closeModal();toast(result.delivered?'Sent to Performance | CH.':'Stored for Performance | CH. Add TELEGRAM_BOT_TOKEN and INTERNAL_CHAT_ID to deliver it.');break}case'v3-resend':if(!isAdmin())return;modal('Resend to Performance | CH',`<p>Client: <strong>${esc(clientById(id).name)}</strong></p><p>This sends the copy-ready message to the internal staff group only. Client WhatsApp groups are still shared by hand.</p>`,`<button class="btn" data-action="close">Close</button><button class="btn primary" data-action="v3-queue-internal" data-id="${id}">Queue internal delivery</button>`);break;
  case'v3-download':await downloadPdf(id,reportDays(kind||state.reportKind,date),kind||state.reportKind);break;
  case'v3-generate':if(canEdit())generateModal(id);break;
  case'v3-feedback-adset':state.feedbackClient=id;resetFeedback();state.feedbackMode='manual';state.feedbackRows=[{...blankRow(),adset:value,campaign:adset(id,value)?.campaign||'',branch:adset(id,value)?.branch||''}];go('feedback/new');break;
  case'v3-feedback-client':state.feedbackClient=id;resetFeedback();go('feedback/new');break;
  case'v3-next-client':{const list=clients(),i=list.findIndex(c=>c.id===state.feedbackClient);state.feedbackClient=list[(i+1)%list.length].id;resetFeedback();render();break}
  case'v3-feedback-mode':state.feedbackMode=value;render();break;
  case'v3-use-example':state.feedbackRaw='22 Oct: 5 responded, 3 not qualified, 2 booked, 1 no budget, 1 won';render();break;
  case'v3-parse':{if(!canEdit())return;state.feedbackRaw=document.getElementById('feedback-paste')?.value||state.feedbackRaw;if(!state.feedbackRaw.trim()){toast('Paste a reply or use the sample first.');return}state.feedbackRedacted=redact(state.feedbackRaw,state.feedbackClient);const parsed=parseFeedback(state.feedbackRedacted,state.feedbackClient);state.feedbackRows=parsed.rows;state.feedbackWarnings=parsed.warnings;state.feedbackConfirmed=false;render();toast(`${parsed.rows.length} rows ready to review. Nothing saved yet.`);break}
  case'v3-add-row':if(!canEdit())return;state.feedbackRows.push(blankRow());state.feedbackConfirmed=false;render();break;
  case'v3-remove-row':if(!canEdit())return;state.feedbackRows.splice(+index,1);state.feedbackConfirmed=false;render();break;
  case'v3-confirm-feedback':{if(!canEdit()||!state.feedbackConfirmed)return;const rows=state.feedbackRows;if(!rows.length||rows.some(r=>!validFeedbackDate(r.date)||!Number.isInteger(+r.count)||+r.count<0||!statuses(r.client).some(s=>s.id===r.status))){toast('Check dates, statuses and non-negative whole-number counts.');return}if(new Set(rows.map(recordKey)).size!==rows.length){toast('Duplicate outcome keys in the preview. Remove duplicates before confirming.');return}const at=new Date().toISOString(),by=(window.__USER?.name||'Performance team');for(const row of rows){const old=db.leadRecords.findIndex(r=>recordKey(r)===recordKey(row)),clean={client:row.client,date:row.date,branch:row.branch,campaign:row.campaign,adset:row.adset,status:row.status,count:Number(row.count),confirmedAt:at,source:'Confirmed entry'};if(old>=0)db.leadRecords[old]=clean;else db.leadRecords.push(clean)}db.leadHistory.push({client:state.feedbackClient,rows:rows.length,date:at,by,source:state.feedbackMode==='manual'?'Manual grid':'Pasted reply · confirmed counts'});persist();const n=rows.length;resetFeedback();render();toast(`${n} outcome rows confirmed. Existing matching counts were replaced.`);break}
  case'v3-client-toggle':if(!isAdmin())return;db.clients[id]={...db.clients[id],[value]:!clientById(id)[value]};persist();render();break;
  case'v3-open-statuses':state.statusClient=id;go('settings/statuses');break;
  case'v3-add-status':if(!isAdmin())return;db.leadStatuses[id]=structuredClone(statuses(id));db.leadStatuses[id].push({id:'custom_'+Date.now(),label:'New status',bucket:'none',synonyms:''});persist();render();break;
  case'v3-remove-status':{if(!isAdmin())return;const st=statuses(id)[+index];if(db.leadRecords.some(r=>r.client===id&&r.status===st.id)){toast('This status has confirmed outcomes. Rename it or change its bucket instead.');return}db.leadStatuses[id]=structuredClone(statuses(id));db.leadStatuses[id].splice(+index,1);persist();render();break}
  case'v3-add-branch':if(!isAdmin())return;db.branchRules[id]??=[];db.branchRules[id].push({code:'NEW',label:'New branch',level:'campaign',type:'prefix',match:'NEW',aliases:''});persist();render();break;
  case'v3-remove-branch':if(!isAdmin())return;db.branchRules[id].splice(+index,1);persist();render();break;
  case'v3-ai-purpose':state.aiPurpose=value;render();break;
  case'v3-refresh-summary':if(!canEdit())return;db.levelSummaries[id]={refreshedAt:new Date().toISOString()};persist();render();toast('Sample summary refreshed locally. No model request was made.');break;
  case'v3-test-purpose':if(!isAdmin())return;modal('Test configuration preview',`<p>Purpose: <strong>${state.aiPurpose.replaceAll('_',' ')}</strong></p><div class="note-box" style="margin:15px 0">This is a sample output preview. The prompt is not executed and no configuration or review is saved.</div><pre class="test-output">${esc(JSON.stringify(state.aiPurpose==='feedback_parser'?{rows:[{date:sampleDate,status:'meeting_booked',count:2}],warnings:[]}:state.aiPurpose==='level_summary'?{summary:'Review confirmed booking efficiency alongside platform lead volume.'}:{summary:'Compare branch booking costs before recommending a budget change.',metric_basis:{metric:'cost_per_booking',value:quality('a').cpb}},null,2))}</pre>`,`<button class="btn primary" data-action="close">Done</button>`);break;
  case'v3-purpose-diff':{const entry=state.aiPurpose==='review'?{settings:db.settings,version:db.settingsVersion,versions:db.versions}:db.aiPurposes[state.aiPurpose],v=entry.versions.find(x=>x.version===+index);if(!v)return;const keys=Object.keys(entry.settings).filter(k=>entry.settings[k]!==v.settings[k]);modal(`Version ${v.version} → ${entry.version}`,keys.map(k=>`<div class="history-entry"><strong>${esc(k)}</strong><p>Previous: ${esc(v.settings[k])}</p><p>Active: ${esc(entry.settings[k])}</p></div>`).join('')||'<p>No configuration fields differ.</p>');break}
 }}
